package zw.co.hyperfeeds.commerce;
import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service class PaymentStateService{private final JdbcClient jdbc;PaymentStateService(JdbcClient j){jdbc=j;}@Transactional void complete(UUID paymentId,boolean paid,String providerStatus,String providerReference,String failure){Map<String,Object>p=jdbc.sql("select p.id,p.order_id,p.status,o.branch_id,o.user_id,o.reference from payments p join orders o on o.id=p.order_id where p.id=:id for update").param("id",paymentId).query().singleRow();if(Set.of("PAID","FAILED","TIMED_OUT").contains(p.get("status")))return;String paymentStatus=paid?"PAID":failure==null?"SENT_TO_SUBSCRIBER":failure; jdbc.sql("update payments set status=:s,provider_reference=coalesce(:ref,provider_reference),failure_reason=:failure,last_polled_at=now(),updated_at=now() where id=:id").param("s",paymentStatus).param("ref",providerReference).param("failure",failure).param("id",paymentId).update();if(!paid&&failure==null)return;String orderStatus=paid?"PAID":"PAYMENT_FAILED";jdbc.sql("update orders set status=:s,updated_at=now() where id=:id").param("s",orderStatus).param("id",p.get("order_id")).update();String op=paid?"on_hand=on_hand-oi.quantity,reserved=reserved-oi.quantity":"reserved=reserved-oi.quantity";jdbc.sql("update branch_inventory bi set "+op+",version=version+1,updated_at=now() from order_items oi where oi.order_id=:o and bi.branch_id=:b and bi.product_id=oi.product_id").param("o",p.get("order_id")).param("b",p.get("branch_id")).update();String title=paid?"Payment received":"Payment unsuccessful";String body=paid?"Order "+p.get("reference")+" has been paid.":"Payment for order "+p.get("reference")+" was not completed.";jdbc.sql("insert into notifications(user_id,type,title,body,data) values(:u,:type,:title,:body,jsonb_build_object('orderId',:order))").param("u",p.get("user_id")).param("type",paid?"ORDER_PAID":"PAYMENT_FAILED").param("title",title).param("body",body).param("order",p.get("order_id").toString()).update();}}
